def has_neighbor(grid, row, col, color):
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        r, c = row + dr, col + dc
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            if grid[r][c] == color:
                return True
    return False

def count_isolated(grid, color, rowsample=None):
    """Count isolated cells of a given color, optionally limiting rows"""
    count = 0
    isolated_rows = []
    for i, row in enumerate(grid):
        if rowsample and i not in rowsample:
            continue
        for j, val in enumerate(row):
            if val == color and not has_neighbor(grid, i, j, color):
                count += 1
                isolated_rows.append((i, j))
    return count, isolated_rows

